CREATE TABLE campaigns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,budget numeric NOT NULL DEFAULT 0 CHECK(budget >= 0),status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,code text UNIQUE NOT NULL,print_code text UNIQUE NOT NULL,campaign_id uuid REFERENCES campaigns(id),category text NOT NULL,platform text NOT NULL,partner text NOT NULL DEFAULT '',city text NOT NULL DEFAULT '',district text NOT NULL DEFAULT '',placement text NOT NULL DEFAULT '',material text NOT NULL DEFAULT '',creative text NOT NULL DEFAULT '',cost numeric NOT NULL DEFAULT 0 CHECK(cost >= 0),launch_date text NOT NULL DEFAULT '',active boolean NOT NULL DEFAULT true,comments text NOT NULL DEFAULT '',utm_source text NOT NULL DEFAULT '',utm_medium text NOT NULL DEFAULT '',utm_campaign text NOT NULL DEFAULT '',utm_content text NOT NULL DEFAULT '',utm_term text NOT NULL DEFAULT '',is_test boolean NOT NULL DEFAULT false,links jsonb NOT NULL DEFAULT '{"vk":"","telegram":"","max":""}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE source_aliases (code text PRIMARY KEY,source_id uuid NOT NULL REFERENCES sources(id));
CREATE TABLE settings (id text PRIMARY KEY,value jsonb NOT NULL);
CREATE TABLE admins (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE NOT NULL,password_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE admin_sessions (id text PRIMARY KEY,admin_id uuid NOT NULL REFERENCES admins(id),csrf text NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE sessions (id uuid PRIMARY KEY,first_source_id uuid REFERENCES sources(id),last_source_id uuid REFERENCES sources(id),first_attribution jsonb NOT NULL,last_attribution jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),last_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE events (id uuid PRIMARY KEY,request_id text UNIQUE NOT NULL,type text NOT NULL,source_id uuid REFERENCES sources(id),campaign_id uuid REFERENCES campaigns(id),session_id uuid REFERENCES sessions(id) ON DELETE SET NULL,network text,attribution jsonb NOT NULL,is_test boolean NOT NULL DEFAULT false,clean boolean NOT NULL,reasons jsonb NOT NULL,device text NOT NULL,browser text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE dedup (key text PRIMARY KEY,expires_at timestamptz NOT NULL);
CREATE TABLE rate_limits (key text PRIMARY KEY,count integer NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE conversions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),external_id text UNIQUE NOT NULL,source_id uuid NOT NULL REFERENCES sources(id),campaign_id uuid REFERENCES campaigns(id),click_id uuid REFERENCES events(id) ON DELETE SET NULL,type text NOT NULL,count integer NOT NULL CHECK(count > 0),origin text NOT NULL,is_test boolean NOT NULL,occurred_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor text NOT NULL,action text NOT NULL,details jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE link_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_id uuid REFERENCES sources(id),network text NOT NULL,old_url text NOT NULL,new_url text NOT NULL,actor text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX source_campaign_idx ON sources(campaign_id);
CREATE INDEX event_time_idx ON events(created_at);
CREATE INDEX event_source_time_idx ON events(source_id,created_at);
CREATE INDEX event_session_idx ON events(session_id);
CREATE INDEX event_campaign_time_idx ON events(campaign_id,created_at);
CREATE INDEX conversion_source_time_idx ON conversions(source_id,occurred_at);
CREATE INDEX dedup_expiry_idx ON dedup(expires_at);
CREATE INDEX rate_expiry_idx ON rate_limits(expires_at);
CREATE INDEX session_last_idx ON sessions(last_at);
